    raise TypeError('expected string, number or boolean')


@dataclass
class Rec:
    id: str
    n: float = 0
    tags: list[str] = field(default_factory=lambda: [])
    label: str = "x"


class T:
    def __init__(self, entity: Rec, ports=None, config: dict | None = None):
